/* --------------------------------------------------------------------
   English word tables
   -------------------------------------------------------------------- */
static const char *const units[] = {"", "one","two","three","four","five","six","seven","eight","nine"};
static const char *const teens[] = {"ten","eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen","eighteen","nineteen"};
static const char *const tens[]  = {"","","twenty","thirty","forty","fifty","sixty","seventy","eighty","ninety"};
static const char *const scale[] = {"", "thousand", "million", "billion", "trillion",
                                    "quadrillion", "quintillion", "sextillion",
                                    "septillion", "octillion", "nonillion",
                                    "decillion"};

/* --------------------------------------------------------------------
   Convert a three‑digit group into ranks (with optional scale)
   -------------------------------------------------------------------- */
static void add_group(int grp, int scaleIdx,
                      unsigned char *ranks, int *len)
{
    int h = grp / 100;
    int rem = grp % 100;

    if (h > 0) {
        push_word(units[h], ranks, len);
        push_word("hundred", ranks, len);
    }

    if (rem >= 10 && rem < 20) {
        push_word(teens[rem - 10], ranks, len);
    } else {
        int t = rem / 10;
        int u = rem % 10;
        if (t > 0) push_word(tens[t], ranks, len);
        if (u > 0) push_word(units[u], ranks, len);
    }

    if (scaleIdx > 0 && grp > 0)
        push_word(scale[scaleIdx], ranks, len);
}

/* --------------------------------------------------------------------
   Convert a number to an array of letter ranks
   -------------------------------------------------------------------- */
static void number_to_ranks(uint64_t n, unsigned char *ranks, int *len)
{
    int groups[22];
    int gcnt = 0;
    while (n > 0) {
        groups[gcnt++] = (int)(n % 1000);
        n /= 1000;
    }

    *len = 0;
    for (int i = gcnt - 1; i >= 0; --i)
        add_group(groups[i], i, ranks, len);
}

/* --------------------------------------------------------------------
   Check whether a number satisfies the split condition
   -------------------------------------------------------------------- */
static bool is_good(uint64_t x)
{
    unsigned char ranks[2048];
    int len;
    number_to_ranks(x, ranks, &len);
    if (len < 2) return false;   /* cannot be split */

    int total[9] = {0};
    for (int i = 0; i < len; ++i) {
        const unsigned char *f = rank_factor[ranks[i]];
        for (int p = 0; p < 9; ++p) total[p] += f[p];
    }

    /* total product must be a perfect square */
    for (int p = 0; p < 9; ++p)
        if (total[p] & 1) return false;

    int target[9];
    for (int p = 0; p < 9; ++p) target[p] = total[p] >> 1;

    int prefix[9] = {0};
    for (int i = 0; i < len - 1; ++i) {   /* split after i */
        const unsigned char *f = rank_factor[ranks[i]];
        for (int p = 0; p < 9; ++p) prefix[p] += f[p];
        bool ok = true;
        for (int p = 0; p < 9; ++p)
            if (prefix[p] != target[p]) { ok = false; break; }
        if (ok) return true;
    }
    return false;
}

/* --------------------------------------------------------------------
   Memoised generator of the sequence
   -------------------------------------------------------------------- */
static seq_t *terms = NULL;
static size_t terms_cnt = 0;
static size_t terms_cap = 0;
static uint64_t last_checked = 1;

seq_t a(idx_t n)
{
    if (!terms) {
        terms_cap = 64;
        terms = (seq_t*)malloc(sizeof(seq_t) * terms_cap);
    }

    /* generate until we have n terms */
    while (terms_cnt < (size_t)n) {
        if (is_good(last_checked)) {
            if (terms_cnt == terms_cap) {
                terms_cap *= 2;
                terms = (seq_t*)realloc(terms, sizeof(seq_t) * terms_cap);
            }
            terms[terms_cnt++] = (seq_t)last_checked;
        }
        ++last_checked;
    }
    return terms[n - 1];
}
